import json
def C(title,scn,prompt,cues,target,en,cando):
    return {"tier":"tier1","level":"B2","title":"Communicative Challenge: "+title,"scenario":scn,"prompt":prompt,"cues":cues,"target":target,"english":en,"canDo":cando}
d={
"b2-dominicana-01":C("A Lake Below Sea Level","You are Meg. You and Carlos are watching a documentary about the Dominican Republic, and he asks which place surprised you most.","Tell Carlos about the lake that surprised you, using a relative clause.",["Name the lake","Say that it is a salt lake and that it is below sea level"],"El lago Enriquillo, que es de agua salada, está bajo el nivel del mar.","Lake Enriquillo, which is a salt lake, is below sea level.","I can describe a mountain, a bay or a lake with a relative clause (*que*, *quien*)."),
"b2-dominicana-02":C("Who Founded Santo Domingo","You are Carlos. You are planning a trip with Meg and reading about the colonial city of Santo Domingo, and she asks who founded it.","Tell Meg who founded Santo Domingo.",["Say that the city was founded","Say who founded it"],"Santo Domingo fue fundada por Bartolomé Colón.","Santo Domingo was founded by Bartolomé Colón.","I can say who founded, built or created something with *fue* / *fueron* + participle."),
"b2-dominicana-03":C("Bachata Goes Round the World","You are Meg. You and Carlos are listening to a podcast about Dominican music, and he asks what happened to bachata after 1990.","Tell Carlos how bachata changed after 1990.",["Say that bachata changed","Say that it became popular in many countries","Give the date"],"La bachata se volvió popular en muchos países después de 1990.","Bachata became popular in many countries after 1990.","I can say how something changed with *ponerse*, *volverse*, *hacerse* or *quedarse*."),
"b2-dominicana-04":C("What Historians Say About 1937","You are Carlos. You are reading an article about the border between the Dominican Republic and Haiti, and Meg asks about the number of deaths in 1937.","Tell Meg what the historians say about the number of deaths in 1937.",["Name your source","Say that the number is still debated"],"Según los historiadores, la cifra de muertos de 1937 se discute todavía.","According to historians, the number of deaths in 1937 is still debated.","I can say who reports or judges something with *según* and *explica que*."),
"b2-dominicana-05":C("If the Grandparents Had Stayed","You are Meg. You and Carlos are reading about Dominican families in New York, and he asks what you think about their story.","Imagine how a family's life would be different if their grandparents had not emigrated.",["Say that the grandparents did not emigrate (as an imagined past)","Say where the family would live today"],"Si sus abuelos no hubieran emigrado, hoy ellos vivirían en la isla.","If their grandparents had not emigrated, they would live on the island today.","I can say what would be different today if a past choice had been different."),
"b2-dominicana-consolidation":C("A Park to Visit","You are Carlos. After the unit on the Dominican Republic, Meg asks which place you would most like to visit.","Tell Meg which park you would like to visit and what it protects.",["Name the park","Say what it protects"],"Los Haitises es un parque que protege manglares y colinas de roca caliza.","Los Haitises is a park that protects mangroves and limestone hills.","I can describe a place or a thing with a relative clause (*que*, *quien*)."),
}
open('/home/user/parlour-read-a/challenges-dominican-republic.json','w',encoding='utf8').write(json.dumps(d,indent=2,ensure_ascii=False))
